import React from 'react';
import { renderHook } from '@testing-library/react-hooks';
import { createContextProvider } from './createContext';

type AppTranslations = {
  'en-US': string;
  'es-419': string;
  'pt-BR': string;
};

type AppsConfiguration = {
  id: string;
  appName: AppTranslations;
  appDescription: AppTranslations;
  appScopePrefix: string;
  baseRoute: string;
  homeRoute: string;
  hidden: boolean;
};

type EnvConfig = {
  appsConfiguration: Array<AppsConfiguration>;
  segmentKey: string;
};

const defaultContext: EnvConfig = {
  appsConfiguration: [],
  segmentKey: 'xxx',
};

describe('createContextProvider', () => {
  it('should render with the right props', () => {
    const [MyCustomProvider, useMyCustomContext] =
      createContextProvider<EnvConfig>('MyCustomProvider');
    const wrapper = ({ children }: { children: React.ReactNode }) => (
      <MyCustomProvider appsConfiguration={[]} segmentKey="xxx">
        {children}
      </MyCustomProvider>
    );
    const { result } = renderHook(() => useMyCustomContext(), { wrapper });
    expect(result.current).toStrictEqual(defaultContext);
  });
});
